import{_ as e,o as a,c as r,ag as s}from"./chunks/framework.4s5LDCII.js";const f=JSON.parse('{"title":"成人糖尿病食养指南（2023年版）","description":"国家卫健委《成人糖尿病食养指南（2023年版）》要点导读：主食定量、全谷物为主、调整进餐顺序，附分地区分季节食谱示例。","frontmatter":{"title":"成人糖尿病食养指南（2023年版）","issuer":"国家卫生健康委办公厅","source_tier":"一级来源","version":"2023年版","published":"2023-01","document_no":"国卫办食品函〔2023〕5号","source_url":"https://www.nhc.gov.cn/sps/c100088/202301/f01895a06c5349ef999f25da833c166d/files/1732844468278_20318.pdf","status":"现行","tags":["糖尿病","食养","血糖","饮食指导"],"reviewed":false,"description":"国家卫健委《成人糖尿病食养指南（2023年版）》要点导读：主食定量、全谷物为主、调整进餐顺序，附分地区分季节食谱示例。"},"headers":[],"relativePath":"guides/diabetes-2023.md","filePath":"guides/diabetes-2023.md"}'),o={name:"guides/diabetes-2023.md"};function d(i,t,n,l,c,h){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="成人糖尿病食养指南-2023年版" tabindex="-1">成人糖尿病食养指南（2023年版） <a class="header-anchor" href="#成人糖尿病食养指南-2023年版" aria-label="Permalink to &quot;成人糖尿病食养指南（2023年版）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本导读由 AI 起草，尚未逐条对照原文校验；一切以原文为准。</p></div><blockquote><p><strong>原文出处</strong>：国家卫生健康委办公厅印发（<a href="https://www.nhc.gov.cn/sps/c100088/202301/f01895a06c5349ef999f25da833c166d/files/1732844468278_20318.pdf" target="_blank" rel="noreferrer">指南全文 PDF</a>，<a href="https://www.nhc.gov.cn/wjw/c100378/202301/7faed9993c9b45aea158c5335346f282.shtml" target="_blank" rel="noreferrer">通知页</a>）· 一级来源</p></blockquote><h2 id="这份文件适合谁" tabindex="-1">这份文件适合谁 <a class="header-anchor" href="#这份文件适合谁" aria-label="Permalink to &quot;这份文件适合谁&quot;">​</a></h2><p>成人糖尿病患者及糖尿病前期人群，以及需要为患者安排日常饮食的家庭成员。</p><h2 id="关键要点-摘要" tabindex="-1">关键要点（摘要） <a class="header-anchor" href="#关键要点-摘要" aria-label="Permalink to &quot;关键要点（摘要）&quot;">​</a></h2><ul><li><strong>主食定量、粗细搭配</strong>：全谷物、杂豆类占主食的一部分，替代部分精白米面。</li><li><strong>多吃蔬菜、水果适量</strong>：蔬菜足量摄入，水果在血糖稳定时适量选用。</li><li><strong>调整进餐顺序与节奏</strong>：先菜后饭、细嚼慢咽，有助餐后血糖平稳（具体建议见原文）。</li><li><strong>规律进餐、不暴饮暴食</strong>：配合规律运动，警惕低血糖；限制饮酒。</li></ul><h2 id="怎么用这份文件" tabindex="-1">怎么用这份文件 <a class="header-anchor" href="#怎么用这份文件" aria-label="Permalink to &quot;怎么用这份文件&quot;">​</a></h2><p>指南按<strong>不同地区、不同季节</strong>给出食谱示例，可就近参考；用药患者的饮食调整请与医生或营养师沟通，具体以原文为准。</p><h2 id="溯源信息" tabindex="-1">溯源信息 <a class="header-anchor" href="#溯源信息" aria-label="Permalink to &quot;溯源信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>国家卫生健康委办公厅</td></tr><tr><td>版本</td><td>2023 年版（现行）</td></tr><tr><td>印发时间</td><td>2023 年 1 月（具体日期待核对原文）</td></tr><tr><td>发文字号</td><td>国卫办食品函〔2023〕5号（待人工复核）</td></tr></tbody></table>',11)])])}const p=e(o,[["render",d]]);export{f as __pageData,p as default};
